void setUp(void)
{
    StoragePortFake_Reset();
}

void tearDown(void) {}

void test_start_initialises_state(void)
{
    playback_session_t s;
    playback_start(&s, 100U);

    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);
    TEST_ASSERT_EQUAL_UINT32(0U, s.bytes_read);
    TEST_ASSERT_EQUAL_UINT32(100U, s.total_data_size);
}

void test_normal_read_returns_requested_bytes(void)
{
    playback_session_t s;
    playback_start(&s, 40U);

    uint8_t data[40];
    memset(data, 0x5A, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[16];
    size_t out_len = 0U;
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);
    TEST_ASSERT_EQUAL_UINT32(16U, out_len);
    TEST_ASSERT_EQUAL_UINT32(16U, s.bytes_read);
    TEST_ASSERT_EQUAL_UINT8(0x5A, out[0]);
}

void test_multi_block_read_accumulates_and_reaches_eof(void)
{
    playback_session_t s;
    playback_start(&s, 30U); /* three 10-byte blocks */

    uint8_t data[30];
    memset(data, 0x11, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[10];
    size_t out_len;

    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL_UINT32(10U, s.bytes_read);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);

    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL_UINT32(20U, s.bytes_read);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);

    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(30U, s.bytes_read);
    TEST_ASSERT_EQUAL_UINT32(10U, out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
}

void test_final_chunk_is_capped_to_remaining_bytes_even_with_larger_buffer(void)
{
    playback_session_t s;
    playback_start(&s, 15U); /* not a multiple of the requested chunk size */

    uint8_t data[15];
    memset(data, 0x22, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[10];
    size_t out_len;

    playback_read_chunk(&s, out, sizeof(out), &out_len); /* takes 10 */
    TEST_ASSERT_EQUAL_UINT32(10U, out_len);

    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    /* Only 5 bytes remained even though the caller offered a 10-byte buffer. */
    TEST_ASSERT_EQUAL_UINT32(5U, out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
}

void test_reading_again_after_eof_is_explicit_and_repeatable(void)
{
    playback_session_t s;
    playback_start(&s, 4U);

    uint8_t data[4] = {1, 2, 3, 4};
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[4];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);

    int reads_before = StoragePortFake_GetReadCallCount();

    /* Calling again after EOF must be safe, return 0 bytes, and not touch
     * the storage port again (deterministic, repeatable). */
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(0U, out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
    TEST_ASSERT_EQUAL_INT(reads_before, StoragePortFake_GetReadCallCount());

    /* Do it again, just to be sure it really is repeatable. */
    result = playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(0U, out_len);
}

void test_read_failure_enters_fault_and_rejects_file(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    StoragePortFake_QueueReadResult(STORAGE_READ_FAIL);

    uint8_t out[16];
    size_t out_len;
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_READ_FAIL, result);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);
    TEST_ASSERT_EQUAL_UINT32(0U, out_len);
}

void test_zero_length_data_size_is_immediate_eof(void)
{
    playback_session_t s;
    playback_start(&s, 0U);

    uint8_t out[16];
    size_t out_len;
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(0U, out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
    /* Must not have called the storage port for a file with no data. */
    TEST_ASSERT_EQUAL_INT(0, StoragePortFake_GetReadCallCount());
}

void test_read_while_idle_is_rejected(void)
{
    playback_session_t s;
    memset(&s, 0, sizeof(s));
    s.state = JACK_PLAYBACK_IDLE;

    uint8_t out[16];
    size_t out_len;
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
}

void test_stop_returns_to_idle(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    playback_stop(&s);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_IDLE, s.state);
}


/* ---------- argument validation ---------- */

void test_playback_rejects_null_arguments(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    uint8_t out[8];
    size_t out_len;

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, playback_read_chunk(NULL, out, sizeof(out), &out_len));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, playback_read_chunk(&s, NULL, sizeof(out), &out_len));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, playback_read_chunk(&s, out, sizeof(out), NULL));
}

void test_playback_rejects_zero_length_buffer(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    uint8_t out[8];
    size_t out_len;

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, playback_read_chunk(&s, out, 0U, &out_len));
    TEST_ASSERT_EQUAL_INT(0, StoragePortFake_GetReadCallCount());
}

void test_playback_null_start_and_stop_do_not_crash(void)
{
    playback_start(NULL, 100U);
    playback_stop(NULL);
    TEST_PASS();
}

