/* ---------- data integrity ---------- */

void test_returned_bytes_match_the_stored_data(void)
{
    playback_session_t s;
    playback_start(&s, 6U);

    uint8_t data[6] = {0x10U, 0x20U, 0x30U, 0x40U, 0x50U, 0x60U};
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[6];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL_UINT32(6U, out_len);
    TEST_ASSERT_EQUAL_MEMORY(data, out, 6U);
}

void test_sequential_reads_return_data_in_order(void)
{
    playback_session_t s;
    playback_start(&s, 4U);

    uint8_t data[4] = {0xAAU, 0xBBU, 0xCCU, 0xDDU};
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[2];
    size_t out_len;

    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL_UINT8(0xAAU, out[0]);
    TEST_ASSERT_EQUAL_UINT8(0xBBU, out[1]);

    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL_UINT8(0xCCU, out[0]);
    TEST_ASSERT_EQUAL_UINT8(0xDDU, out[1]);
}

/* ---------- fault behaviour ---------- */

void test_fault_state_is_sticky_and_blocks_further_reads(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    StoragePortFake_QueueReadResult(STORAGE_READ_FAIL);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len); /* -> FAULT */

    int reads_before = StoragePortFake_GetReadCallCount();
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);
    TEST_ASSERT_EQUAL_INT(reads_before, StoragePortFake_GetReadCallCount());
}

void test_fault_records_the_underlying_reason(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    StoragePortFake_QueueReadResult(STORAGE_CORRUPT);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, s.last_fault);
}

void test_read_failure_partway_through_preserves_progress_count(void)
{
    playback_session_t s;
    playback_start(&s, 20U);

    uint8_t data[20];
    memset(data, 0x77, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);
    StoragePortFake_QueueReadResult(STORAGE_READ_FAIL);

    uint8_t out[10];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len); /* 10 bytes fine */
    playback_read_chunk(&s, out, sizeof(out), &out_len); /* then fails */

    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);
    TEST_ASSERT_EQUAL_UINT32(10U, s.bytes_read);
}

void test_restart_after_fault_gives_a_clean_session(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    StoragePortFake_QueueReadResult(STORAGE_READ_FAIL);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);

    playback_start(&s, 50U);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);
    TEST_ASSERT_EQUAL_UINT32(0U, s.bytes_read);
    TEST_ASSERT_EQUAL_UINT32(50U, s.total_data_size);
    TEST_ASSERT_EQUAL(STORAGE_OK, s.last_fault);
}

void test_stop_from_fault_leaves_fault_visible(void)
{
    playback_session_t s;
    playback_start(&s, 100U);
    StoragePortFake_QueueReadResult(STORAGE_READ_FAIL);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);
    playback_stop(&s);

    /* Fault must survive a stop so the UI can still report it. */
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_FAULT, s.state);
}

void test_stop_from_eof_returns_to_idle(void)
{
    playback_session_t s;
    playback_start(&s, 0U);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);

    playback_stop(&s);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_IDLE, s.state);
}

/* ---------- multi-step realistic sequences ---------- */

void test_full_playback_of_a_realistic_file(void)
{
    /* 512 bytes played out in 64-byte blocks - 8 reads exactly. */
    playback_session_t s;
    playback_start(&s, 512U);

    uint8_t data[512];
    memset(data, 0x5AU, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[64];
    size_t out_len;
    int reads = 0;

    while (s.state == JACK_PLAYBACK_PLAYING)
    {
        playback_read_chunk(&s, out, sizeof(out), &out_len);
        reads++;
        TEST_ASSERT_TRUE(reads <= 20); /* guard against a runaway loop */
    }

    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
    TEST_ASSERT_EQUAL_UINT32(512U, s.bytes_read);
    TEST_ASSERT_EQUAL_INT(8, reads);
}

void test_replay_the_same_file_after_stopping(void)
{
    playback_session_t s;
    uint8_t data[8];
    memset(data, 0x33U, sizeof(data));
    uint8_t out[8];
    size_t out_len;

    playback_start(&s, 8U);
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);
    playback_read_chunk(&s, out, sizeof(out), &out_len);
    playback_stop(&s);

    /* Replay - the UI offers this on the PLAY screen. */
    StoragePortFake_SetReadData(data, sizeof(data));
    playback_start(&s, 8U);
    storage_result_t result = playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(8U, out_len);
}

void test_never_requests_more_bytes_than_the_file_contains(void)
{
    playback_session_t s;
    playback_start(&s, 5U);

    uint8_t data[100];
    memset(data, 0x01U, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[100];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);

    /* The fake holds 100 bytes but the file declares only 5 - the module
     * must not over-read past the end of the declared audio data. */
    TEST_ASSERT_EQUAL_UINT32(5U, out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
}

void test_short_read_from_storage_is_handled_without_overrunning(void)
{
    /* File claims 20 bytes but storage only actually holds 12. */
    playback_session_t s;
    playback_start(&s, 20U);

    uint8_t data[12];
    memset(data, 0x09U, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[20];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL_UINT32(12U, out_len);
    TEST_ASSERT_EQUAL_UINT32(12U, s.bytes_read);
    /* Still PLAYING, since the declared size has not been reached. */
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);
}

void test_single_byte_file_plays_and_reaches_eof(void)
{
    playback_session_t s;
    playback_start(&s, 1U);

    uint8_t data[1] = {0x42U};
    StoragePortFake_SetReadData(data, sizeof(data));
    StoragePortFake_QueueReadResult(STORAGE_OK);

    uint8_t out[8];
    size_t out_len;
    playback_read_chunk(&s, out, sizeof(out), &out_len);

    TEST_ASSERT_EQUAL_UINT32(1U, out_len);
    TEST_ASSERT_EQUAL_UINT8(0x42U, out[0]);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): the playback_start_at tests below */
/* ---------- playback_start_at: start part-way (effect switch, resume) ---------- */

void test_start_at_an_offset_reads_the_rest_and_then_reaches_eof(void)
{
    playback_session_t s;
    playback_start_at(&s, 1000U, 400U);
    TEST_ASSERT_EQUAL_UINT32(400U, s.bytes_read);

    uint8_t data[600];
    memset(data, 0x11, sizeof(data));
    StoragePortFake_SetReadData(data, sizeof(data));
    uint8_t out[1000];
    size_t out_len = 0U;
    TEST_ASSERT_EQUAL(STORAGE_OK, playback_read_chunk(&s, out, sizeof(out), &out_len));
    TEST_ASSERT_EQUAL_UINT32(600U, (uint32_t)out_len);       /* only what is left after the offset */
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
}

void test_start_at_the_end_is_eof_at_the_first_read(void)
{
    playback_session_t s;
    playback_start_at(&s, 1000U, 1000U);
    uint8_t out[16];
    size_t out_len = 99U;
    TEST_ASSERT_EQUAL(STORAGE_OK, playback_read_chunk(&s, out, sizeof(out), &out_len));
    TEST_ASSERT_EQUAL_UINT32(0U, (uint32_t)out_len);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_EOF, s.state);
    TEST_ASSERT_EQUAL(0, StoragePortFake_GetReadCallCount());   /* no card access */
}

void test_start_at_clamps_an_offset_past_the_end(void)
{
    playback_session_t s;
    playback_start_at(&s, 1000U, 5000U);
    TEST_ASSERT_EQUAL_UINT32(1000U, s.bytes_read);
    TEST_ASSERT_EQUAL(JACK_PLAYBACK_PLAYING, s.state);
}

void test_start_at_an_odd_offset_rounds_down_to_a_whole_sample(void)
{
    playback_session_t s;
    playback_start_at(&s, 1000U, 401U);
    TEST_ASSERT_EQUAL_UINT32(400U, s.bytes_read);
}

